import pytest

from fastjsonschema import JsonSchemaException, compile


@pytest.mark.parametrize('value, expected', [
    ([], []),
    ([1, 'a'], [1, 'a']),
    ((1, 2), (1, 2)),
    (('a', 'b'), ('a', 'b')),
])
def test_array_with_tuples(asserter, value, expected):
    asserter({'type': 'array'}, value, expected)


def test_array_with_tuples_min_max_items(asserter):
    # Test minItems
    asserter({'type': 'array', 'minItems': 2}, (1, 2), (1, 2))
    with pytest.raises(JsonSchemaException) as exc:
        compile({'type': 'array', 'minItems': 2})(())
    assert exc.value.rule == 'minItems'

    # Test maxItems
    asserter({'type': 'array', 'maxItems': 2}, (1, 2), (1, 2))
    with pytest.raises(JsonSchemaException) as exc:
        compile({'type': 'array', 'maxItems': 2})(1, 2, 3)
    assert exc.value.rule == 'maxItems'


def test_array_with_tuples_unique_items(asserter):
    asserter({'type': 'array', 'uniqueItems': True}, (1, 2), (1, 2))
    with pytest.raises(JsonSchemaException) as exc:
        compile({'type': 'array', 'uniqueItems': True})(1, 1)
    assert exc.value.rule == 'uniqueItems'


def test_array_with_tuples_items_validation(asserter):
    asserter({
        'type': 'array',
        'items': {'type': 'number'},
    }, (1, 2), (1, 2))

    with pytest.raises(JsonSchemaException) as exc:
        compile({
            'type': 'array',
            'items': {'type': 'number'},
        })(('a', 2))
    assert exc.value.rule == 'type'


def test_array_with_tuples_items_with_defaults(asserter):
    # tuples should not append defaults (they're immutable)
    asserter({
        'type': 'array',
        'items': [{'type': 'integer', 'default': 0}, {'type': 'string', 'default': 'x'}],
    }, (1,), (1,))

    # lists should append defaults
    v = compile({
        'type': 'array',
        'items': [{'type': 'integer', 'default': 0}, {'type': 'string', 'default': 'x'}],
    })
    assert v([1]) == [1, 'x']


def test_array_with_tuples_contains(asserter):
    asserter({
        'type': 'array',
        'contains': {'type': 'number'},
    }, ('a', 1), ('a', 1))

    with pytest.raises(JsonSchemaException) as exc:
        compile({
            'type': 'array',
            'contains': {'type': 'number'},
        })(('a', 'b'))
    assert exc.value.rule == 'contains'
